import json
from datetime import datetime
from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, Output
from lfx.schema.message import Message


class DecisionEngine(Component):
    display_name = "Decision Engine"
    description = "Tentukan rekomendasi aksi berdasarkan rules deterministik"

    inputs = [
        DataInput(name="risk_data", display_name="Risk Classifier Output", required=True),
    ]

    outputs = [
        Output(display_name="Decision Data (JSON)", name="decision_data", method="decide"),
    ]

    def decide(self) -> Message:
        result = self._make_decision(self.risk_data.data)
        self.status = result
        return Message(text=json.dumps(result, ensure_ascii=False))

    def _make_decision(self, risk_data: dict) -> dict:
        pending_decision = None
        status = risk_data["status"]
        overdue = risk_data.get("overdue_receivables", [])
        if status == "KRITIS" and overdue:
            sorted_overdue = sorted(overdue, key=lambda x: x["overdue_days"], reverse=True)
            top = sorted_overdue[0]
            pending_decision = {
                "type": "collect_receivable",
                "target": top["buyer"],
                "amount": top["amount"],
                "overdue_days": top["overdue_days"],
                "recommendation": f"Tagih {top['buyer']} hari ini — piutang Rp {top['amount']:,} telat {top['overdue_days']} hari".replace(",", "."),
                "all_receivables": sorted_overdue,
            }
        stock_need = risk_data.get("pending_stock_need")
        if stock_need and status != "KRITIS":
            best = self._find_settlement_before(risk_data["settlements_net"], stock_need["stock_depletes_on"])
            pending_decision = self._build_restock_decision(best, stock_need, status)
        return {
            "store_owner": risk_data["owner_name"],
            "store_id": risk_data["store_id"],
            "status": status,
            "urgency_level": risk_data["urgency_level"],
            "current_cash": risk_data["current_cash_balance"],
            "runway_days": risk_data["runway_days"],
            "min_balance_amount": risk_data["min_balance_amount"],
            "settlements": risk_data["settlements_net"],
            "total_incoming_this_week": risk_data["total_net_incoming"],
            "pending_decision": pending_decision,
            "daily_projection": risk_data["daily_projection"],
        }

    def _find_settlement_before(self, settlements, deadline_str):
        try:
            deadline = datetime.fromisoformat(deadline_str).date()
        except ValueError:
            return None
        candidates = []
        for s in settlements:
            try:
                d = datetime.fromisoformat(s["disbursement_date"]).date()
                if d <= deadline:
                    candidates.append((d, s))
            except ValueError:
                continue
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0])
        return candidates[0][1]

    def _build_restock_decision(self, best_settlement, stock_need, status):
        item = stock_need["item"]
        cost = stock_need["estimated_cost"]
        depletes = stock_need["stock_depletes_on"]
        if best_settlement:
            net = best_settlement["net_amount"]
            mkt = best_settlement["marketplace"]
            disburse_date = best_settlement["disbursement_date"]
            if net >= cost:
                recommendation = f"Restock {item} setelah settlement {mkt} cair ({disburse_date}) — dana cukup Rp {net:,}".replace(",", ".")
            else:
                shortfall = cost - net
                recommendation = f"Restock {item} butuh Rp {cost:,} — settlement {mkt} hanya Rp {net:,}, kurang Rp {shortfall:,}".replace(",", ".")
        else:
            recommendation = f"Tidak ada settlement sebelum stok {item} habis ({depletes}). Pertimbangkan pinjaman."
        return {
            "type": "restock",
            "item": item,
            "cost": cost,
            "stock_depletes": depletes,
            "best_settlement": best_settlement,
            "recommendation": recommendation,
        }

    def build(self):
        return self.decide

import json
from lfx.custom.custom_component.component import Component
from lfx.io import MessageInput, Output
from lfx.schema.message import Message


class OutputValidator(Component):
    display_name = "Output Validator"
    description = "Validasi output LLM — pastikan angka kritis tidak hilang"

    inputs = [
        MessageInput(name="llm_output", display_name="LLM Raw Output", required=True),
        MessageInput(name="decision_data", display_name="Decision Engine Output", required=True),
    ]

    outputs = [
        Output(display_name="Validated Output", name="validated", method="validate"),
    ]

    def validate(self) -> Message:
        result = self._validate(self.llm_output.text, json.loads(self.decision_data.text))
        self.status = result
        return Message(text=json.dumps(result, ensure_ascii=False))

    def _validate(self, llm_output: str, decision_data: dict) -> dict:
        REQUIRED_FIELDS = ["status_line", "incoming_funds", "key_decision", "full_message", "action_button"]
        try:
            clean = llm_output.strip()
            if clean.startswith("```"):
                lines = clean.split("\n")
                clean = "\n".join(lines[1:-1])
            parsed = json.loads(clean)
        except json.JSONDecodeError as e:
            return {"valid": False, "parsed": None, "reason": f"invalid_json: {e}", "missing_numbers": []}
        missing_fields = [f for f in REQUIRED_FIELDS if f not in parsed]
        if missing_fields:
            return {"valid": False, "parsed": parsed, "reason": f"missing_fields: {missing_fields}", "missing_numbers": []}
        full_message = parsed.get("full_message", "")
        critical_numbers = self._extract_critical_numbers(decision_data)
        missing_numbers = [n for n in critical_numbers if f"{n:,}".replace(",", ".") not in full_message]
        if missing_numbers:
            return {"valid": False, "parsed": parsed, "reason": "missing_numbers", "missing_numbers": missing_numbers}
        return {"valid": True, "parsed": parsed, "reason": None, "missing_numbers": []}

    def _extract_critical_numbers(self, decision_data: dict) -> list:
        numbers = []

        # Saldo kas saat ini
        if decision_data.get("current_cash", 0) > 10000:
            numbers.append(int(decision_data["current_cash"]))

        # Net amount per settlement - WAJIB muncul individual
        for s in decision_data.get("settlements", []):
            if s.get("net_amount", 0) > 10000:
                numbers.append(int(s["net_amount"]))

        # piutang jatuh tempo - jika ada
        decision = decision_data.get("pending_decision")
        if decision and decision.get("type") == "collect_receivable":
            if decision.get("amount", 0) > 10000:
                numbers.append(int(decision["amount"]))

        return numbers

    def build(self):
        return self.validate
